package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodCaps;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Opens the selected claims in list order (people by their position in the list, each person's
 * claims newest first), numbering each as it is opened. A claim that cannot be opened (not a
 * draft, dated inside a closed period, its person at its period's cap, not on the sheet, above the note threshold with an empty note) is refused and left as it is; every one is
 * refused when the permission matrix does not allow the user's role to open, or the sheet is
 * archived. Each claim opened is logged and audited as a single open is: its CLAIM_OPENED line,
 * then the figures it moved.
 */
public class OpenSelectedClaims {
    public void open(@Val Sheet sheet, @Val BulkOpenRequest request, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, SheetRepository sheets, RateRepository rates,
            RoleRepository roles, SettingsRepository settings, ClaimLogRepository log, HttpServletRequest http, Audit audit,
            Out<BulkOpenResponse> result) {
        String user = Audit.user(http);
        Set<Long> selected = new HashSet<>();
        for (String id : request.claimIds()) {
            try {
                selected.add(Long.parseLong(id.trim()));
            } catch (NumberFormatException | NullPointerException e) {
                // not an id: no claim on the sheet, so refused below
            }
        }
        int requested = new HashSet<>(request.claimIds()).size();
        int opened = 0;
        if (sheet.archived() || !settings.find(sheet.id()).allows("open", roles.roleOf(sheet.id(), user))) {
            result.set(new BulkOpenResponse(0, requested));
            return;
        }
        Rollup before = rollup(sheet, sheets, people, claims, rates, settings);
        for (Person person : people.findAll(sheet.id())) {
            List<Claim> theirs = claims.findByPerson(sheet.id(), person.getId());
            for (Claim claim : theirs) {
                if (!selected.contains(claim.getId())) continue;
                if (OpenClaim.needsNote(sheet, claim, people, rates, settings)) continue;
                if (!opens(sheet, claim, periods, claims)) continue;
                claim.setOpenedBy(user);
                claim.setNumber(ClaimNumbers.next(sheet, claim, settings.find(sheet.id()), periods, claims));
                claims.save(claim);
                log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
                opened++;
                audit.record(ClaimAudit.line(claim.getStatus().auditEvent(), sheet, user, person, claim));
                Rollup after = rollup(sheet, sheets, people, claims, rates, settings);
                after.changesSince(before, sheet.id(), user).forEach(audit::record);
                before = after;
            }
        }
        result.set(new BulkOpenResponse(opened, requested - opened));
    }

    /** Moves the claim to OPEN when its status, period and period's cap allow it and no one opened it first. */
    private static boolean opens(Sheet sheet, Claim claim, PeriodRepository periods, ClaimRepository claims) {
        if (periods.closedOn(sheet.id(), claim.getDueBy()) != null) return false;
        if (PeriodCaps.full(sheet, claim, periods, claims) != null) return false;
        try {
            claim.moveTo(ClaimStatus.OPEN);
        } catch (InvalidClaimStatusException e) {
            return false;
        }
        return claims.markOpened(claim);
    }

    private static Rollup rollup(Sheet sheet, SheetRepository sheets, PersonRepository people, ClaimRepository claims,
            RateRepository rates, SettingsRepository settings) {
        return Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates, settings.find(sheet.id()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A claim's audit record: its person, its amount as the screen shows it, its date, and its number
 * when it has one (a voided claim keeps the number it had).
 */
final class ClaimAudit {
    private ClaimAudit() {}

    static String line(String event, Sheet sheet, String user, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + sheet.id() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Approves a PENDING claim: it is settled, its due fixed at this moment at its live figure (a
 * PENDING claim is bound by no statement) with the late charge it has gained by the sheet's today.
 * Only a steward may approve it, and not the user who opened it or last edited it; and not while it has no proofs
 * when its due is above the proof threshold in force on its date.
 */
public class ApproveClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settings, HttpServletRequest request)
            throws InvalidClaimStatusException, ApprovalException {
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new ApprovalException("Only a steward may approve a claim: " + user + " is a clerk");
        }
        if (user.equals(claim.getOpenedBy())) {
            throw new ApprovalException("A claim cannot be approved by " + user + ", who opened it");
        }
        if (claim.isOwnedBy(user)) {
            throw new ApprovalException("A claim cannot be approved by " + user + ", who last edited it");
        }
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings sheetSettings = settings.find(sheet.id());
        // Read while the claim is still PENDING: its live figure and its late charge.
        java.math.BigDecimal due = ClaimFigure.withLate(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()),
                sheetSettings, sheet.today());
        if (sheetSettings.needsProof(due, person.gradeOn(claim.getDate()), claim.getDate(), claim.getProofs())) {
            throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
        }
        claim.approve(due);
    }
}
# Approve a PENDING claim (a steward, not its opener). A change its status does not allow is a 409 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApproveClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
# The status it was saved at, with who, when and its due then.
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimApproved
  govern: [ transaction ]
  next: notify
# After the claim's own line: one line per watcher of its person, once it is settled.
notify:
  class: net.officefloor.hq.app.watch.NotifyWatchers
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Open the selected claims together, in list order. Each that cannot be opened is refused and left
# as it is; the response tells how many were opened and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkOpen
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: open
# Each claim opened is audited as it is opened: its own line, then the figures it moved.
open:
  class: net.officefloor.hq.app.claim.OpenSelectedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
  govern: [ transaction ]

