141	/**
142	 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
143	 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
144	 * from other dates and replacing one recorded from the same date. An action's entry in the
145	 * permission matrix is not dated: it replaces the one before, nor is the parent sheet, nor the alert threshold.
146	 */
147	public class SaveSettings {
148	    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
149	            net.officefloor.hq.app.sheet.SheetRepository sheets, Out<Settings> settingsOut) {
150	        if (input.parentChanged()) sheets.saveParent(sheet.id(), input.parent());
151	        Settings now = repository.find(sheet.id());
152	        if (input.policyDateChanged() || input.periodNumberingFromChanged() || input.graceDaysChanged()
153	                || input.entryDateChanged() || input.potChanged() || input.fiscalStartMonthChanged()
154	                || input.alertThresholdChanged()) {
155	            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
156	                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
157	                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms(),
158	                    input.graceDaysChanged() ? input.graceDays() : now.graceDays(),
159	                    input.entryDateChanged() ? input.entryDate() : now.entryDate(),
160	                    input.potChanged() ? input.pot() : now.pot(),
161	                    input.fiscalStartMonthChanged() ? input.fiscalStartMonth() : now.fiscalStartMonth(),
162	                    input.alertThresholdChanged() ? input.alertThreshold() : now.alertThreshold()));
163	        }
164	        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
165	        java.util.Map<String, String> values = new java.util.LinkedHashMap<>(input.datedValues());
166	        values.putAll(input.gradeTermsValues());
167	        values.putAll(input.gradeGraceValues());
168	        values.putAll(input.gradeProofThresholdValues());
169	        if (input.capValue() != null) values.put(Settings.CAP, input.capValue());
170	        if (input.proofThresholdValue() != null) values.put(Settings.PROOF_THRESHOLD, input.proofThresholdValue());
171	        if (input.noteThresholdValue() != null) values.put(Settings.NOTE_THRESHOLD, input.noteThresholdValue());
172	        if (input.roundingValue() != null) values.put(Settings.ROUNDING, input.roundingValue());
173	        values.forEach((key, value) -> {
174	            LocalDate from = input.from().getOrDefault(key, sheet.today());
175	            repository.record(sheet.id(), key, from, value);
176	        });
177	        settingsOut.set(repository.find(sheet.id()));
178	    }
179	}
