298	                gradeProofThreshold(settings),
299	                show(settings.pot()), parent == null ? "" : parent,
300	                Integer.toString(settings.fiscalStart()), show(settings.alertThreshold()),
301	                rounding(settings.valueOn(Settings.ROUNDING, today)));
302	    }
303	
304	    private static String rounding(String value) {
305	        return value == null ? "" : value;
306	    }
307	
308	    private static String show(java.math.BigDecimal figure) {
309	        return figure == null ? "" : figure.setScale(2).toPlainString();
310	    }
