312	    private static Map<String, String> gradeTerms(Settings settings) {
313	        Map<String, String> shown = new LinkedHashMap<>();
314	        for (String grade : Settings.GRADES) {
315	            Integer own = settings.gradeTermsOn(grade, settings.today());
316	            shown.put(grade, own == null ? "" : own.toString());
317	        }
318	        return shown;
