345	    private static Map<String, List<Dated>> dated(Settings settings) {
346	        Map<String, List<Dated>> shown = new LinkedHashMap<>();
347	        settings.dated().forEach((key, values) -> {
348	            List<Dated> list = new ArrayList<>();
349	            values.forEach((from, value) -> list.add(new Dated(from.toString(), value)));
350	            shown.put(key, list);
351	        });
