367	public class ValidateSettings {
368	    private static final Pattern FIGURE = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");
369	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
370	    private static final Pattern MONTH = Pattern.compile("0?[1-9]|1[0-2]");
371	    private static final java.util.Set<String> DATED = java.util.Set.of(Settings.CLERK_LIMIT, Settings.FLOOR,
372	            Settings.TERMS, Settings.LATE_PCT, Settings.CAP, Settings.gradeTermsKey("A"), Settings.gradeTermsKey("B"),
373	            Settings.gradeTermsKey("C"), Settings.PROOF_THRESHOLD, Settings.NOTE_THRESHOLD, Settings.ROUNDING,
374	            Settings.gradeGraceKey("A"), Settings.gradeGraceKey("B"), Settings.gradeGraceKey("C"),
375	            Settings.gradeProofThresholdKey("A"), Settings.gradeProofThresholdKey("B"),
376	            Settings.gradeProofThresholdKey("C"));
377	
378	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body)
379	            throws InvalidSettingException {
380	        boolean limitChanged = request != null && request.clerkLimit() != null;
381	        BigDecimal limit = null;
382	        if (limitChanged && !request.clerkLimit().trim().isEmpty()) {
383	            String value = request.clerkLimit().trim();
384	            if (!FIGURE.matcher(value).matches()) {
385	                throw new InvalidSettingException("A clerk limit is 0.00 or more, with up to two decimals");
386	            }
387	            limit = new BigDecimal(value).setScale(2);
388	        }
389	        BigDecimal floor = null;
390	        if (request != null && request.floor() != null) {
391	            String value = request.floor().trim();
392	            if (!FIGURE.matcher(value).matches()) {
393	                throw new InvalidSettingException("A floor is 0.00 or more, with up to two decimals");
394	            }
395	            floor = new BigDecimal(value).setScale(2);
396	        }
397	        Integer terms = null;
398	        if (request != null && request.terms() != null) {
399	            String value = request.terms().trim();
400	            if (!DAYS.matcher(value).matches()) {
401	                throw new InvalidSettingException("Terms are a whole number of days, 0 or more");
402	            }
403	            terms = Integer.valueOf(value);
404	        }
405	        BigDecimal latePct = null;
406	        if (request != null && request.latePct() != null) {
407	            String value = request.latePct().trim();
408	            if (!FIGURE.matcher(value).matches()) {
409	                throw new InvalidSettingException("A late percent is 0.00 or more, with up to two decimals");
410	            }
411	            latePct = new BigDecimal(value).setScale(2);
412	        }
413	        boolean policyChanged = request != null && request.policyDate() != null;
414	        LocalDate policyDate = null;
415	        if (policyChanged && !request.policyDate().trim().isEmpty()) {
416	            try {
417	                policyDate = LocalDate.parse(request.policyDate().trim());
418	            } catch (DateTimeParseException e) {
419	                throw new InvalidSettingException("A policy date is a date, yyyy-MM-dd, or blank");
420	            }
421	        }
422	        boolean numberingChanged = request != null && request.periodNumberingFrom() != null;
423	        LocalDate numberingFrom = null;
424	        if (numberingChanged && !request.periodNumberingFrom().trim().isEmpty()) {
425	            try {
426	                numberingFrom = LocalDate.parse(request.periodNumberingFrom().trim());
427	            } catch (DateTimeParseException e) {
428	                throw new InvalidSettingException("A period numbering from is a date, yyyy-MM-dd, or blank");
429	            }
430	        }
431	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
432	        if (request != null && request.gradeTerms() != null) {
433	            for (String grade : request.gradeTerms().keySet()) {
434	                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
435	            }
436	            for (String grade : Settings.GRADES) {
437	                String value = request.gradeTerms().get(grade);
438	                if (value == null) continue;
439	                value = value.trim();
440	                if (value.isEmpty()) {
441	                    gradeTerms.put(grade, null);
442	                } else if (!DAYS.matcher(value).matches()) {
443	                    throw new InvalidSettingException("Terms are a whole number of days, 0 or more, or blank");
444	                } else {
445	                    gradeTerms.put(grade, Integer.valueOf(value));
446	                }
447	            }
448	        }
449	        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
450	        if (request != null && request.gradeGrace() != null) {
451	            for (String grade : request.gradeGrace().keySet()) {
452	                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
453	            }
454	            for (String grade : Settings.GRADES) {
455	                String value = request.gradeGrace().get(grade);
456	                if (value == null) continue;
457	                value = value.trim();
458	                if (value.isEmpty()) {
459	                    gradeGrace.put(grade, null);
460	                } else if (!DAYS.matcher(value).matches()) {
461	                    throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
462	                } else {
463	                    gradeGrace.put(grade, Integer.valueOf(value));
464	                }
465	            }
466	        }
467	        Map<String, BigDecimal> gradeProofThreshold = new LinkedHashMap<>();
468	        if (request != null && request.gradeProofThreshold() != null) {
469	            for (String grade : request.gradeProofThreshold().keySet()) {
470	                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
471	            }
472	            for (String grade : Settings.GRADES) {
473	                String value = request.gradeProofThreshold().get(grade);
474	                if (value == null) continue;
475	                value = value.trim();
476	                if (value.isEmpty()) {
477	                    gradeProofThreshold.put(grade, null);
478	                } else if (!FIGURE.matcher(value).matches()) {
479	                    throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
480	                } else {
481	                    gradeProofThreshold.put(grade, new BigDecimal(value).setScale(2));
482	                }
483	            }
484	        }
485	        boolean capChanged = request != null && request.cap() != null;
486	        BigDecimal cap = null;
487	        if (capChanged && !request.cap().trim().isEmpty()) {
488	            String value = request.cap().trim();
489	            if (!FIGURE.matcher(value).matches()) {
490	                throw new InvalidSettingException("A cap is 0.00 or more, with up to two decimals, or blank");
491	            }
492	            cap = new BigDecimal(value).setScale(2);
493	        }
494	        boolean thresholdChanged = request != null && request.proofThreshold() != null;
495	        BigDecimal threshold = null;
496	        if (thresholdChanged && !request.proofThreshold().trim().isEmpty()) {
497	            String value = request.proofThreshold().trim();
498	            if (!FIGURE.matcher(value).matches()) {
499	                throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
500	            }
501	            threshold = new BigDecimal(value).setScale(2);
502	        }
503	        boolean noteThresholdChanged = request != null && request.noteThreshold() != null;
504	        BigDecimal noteThreshold = null;
505	        if (noteThresholdChanged && !request.noteThreshold().trim().isEmpty()) {
506	            String value = request.noteThreshold().trim();
507	            if (!FIGURE.matcher(value).matches()) {
508	                throw new InvalidSettingException("A note threshold is 0.00 or more, with up to two decimals, or blank");
509	            }
510	            noteThreshold = new BigDecimal(value).setScale(2);
511	        }
512	        boolean roundingChanged = request != null && request.rounding() != null;
513	        String rounding = null;
514	        if (roundingChanged && !request.rounding().trim().isEmpty()) {
515	            String value = request.rounding().trim();
516	            if (!Settings.HALF_UP.equals(value) && !Settings.HALF_EVEN.equals(value)) {
517	                throw new InvalidSettingException("A rounding mode is half-up or half-even, or blank");
518	            }
519	            rounding = value;
520	        }
521	        Map<String, String> perms = new LinkedHashMap<>();
522	        if (request != null && request.perms() != null) {
523	            for (String action : request.perms().keySet()) {
524	                if (!Settings.ACTIONS.contains(action)) {
525	                    throw new InvalidSettingException("An action is one of " + String.join(", ", Settings.ACTIONS));
526	                }
527	            }
528	            for (String action : Settings.ACTIONS) {
529	                String value = request.perms().get(action);
530	                if (value == null) continue;
531	                value = value.trim();
532	                java.util.List<String> roles = new java.util.ArrayList<>();
533	                if (!value.isEmpty()) {
534	                    for (String role : value.split(",", -1)) {
535	                        role = role.trim();
536	                        if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
537	                            throw new InvalidSettingException("Roles are clerk or steward, separated by commas, or blank");
538	                        }
539	                        if (!roles.contains(role)) roles.add(role);
540	                    }
541	                }
542	                perms.put(action, String.join(",", roles));
543	            }
544	        }
545	        boolean graceChanged = request != null && request.graceDays() != null;
546	        Integer graceDays = null;
547	        if (graceChanged && !request.graceDays().trim().isEmpty()) {
548	            String value = request.graceDays().trim();
549	            if (!DAYS.matcher(value).matches()) {
550	                throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
551	            }
552	            graceDays = Integer.valueOf(value);
553	        }
554	        boolean entryChanged = request != null && request.entryDate() != null;
555	        LocalDate entryDate = null;
556	        if (entryChanged && !request.entryDate().trim().isEmpty()) {
557	            try {
558	                entryDate = LocalDate.parse(request.entryDate().trim());
559	            } catch (DateTimeParseException e) {
560	                throw new InvalidSettingException("An entry date is a date, yyyy-MM-dd, or blank");
561	            }
562	        }
563	        boolean potChanged = request != null && request.pot() != null;
564	        BigDecimal pot = null;
565	        if (potChanged && !request.pot().trim().isEmpty()) {
566	            String value = request.pot().trim();
567	            if (!FIGURE.matcher(value).matches()) {
568	                throw new InvalidSettingException("A pot is 0.00 or more, with up to two decimals, or blank");
569	            }
570	            pot = new BigDecimal(value).setScale(2);
571	        }
572	        boolean parentChanged = request != null && request.parent() != null;
573	        String parent = parentChanged && !request.parent().trim().isEmpty() ? request.parent().trim() : null;
574	        boolean fiscalChanged = request != null && request.fiscalStartMonth() != null;
575	        Integer fiscalStartMonth = null;
576	        if (fiscalChanged) {
577	            String value = request.fiscalStartMonth().trim();
578	            if (!MONTH.matcher(value).matches()) {
579	                throw new InvalidSettingException("A fiscal start month is a month, 1 to 12");
580	            }
581	            fiscalStartMonth = Integer.valueOf(value);
582	        }
583	        boolean alertChanged = request != null && request.alertThreshold() != null;
584	        BigDecimal alertThreshold = null;
585	        if (alertChanged && !request.alertThreshold().trim().isEmpty()) {
586	            String value = request.alertThreshold().trim();
587	            if (!FIGURE.matcher(value).matches()) {
588	                throw new InvalidSettingException("An alert threshold is 0.00 or more, with up to two decimals, or blank");
589	            }
590	            alertThreshold = new BigDecimal(value).setScale(2);
591	        }
592	        Map<String, LocalDate> from = new LinkedHashMap<>();
593	        if (request != null && request.from() != null) {
594	            for (Map.Entry<String, String> entry : request.from().entrySet()) {
595	                if (!DATED.contains(entry.getKey())) throw new InvalidSettingException("Only a figure setting has a from-date");
596	                String value = entry.getValue() == null ? "" : entry.getValue().trim();
597	                if (value.isEmpty()) continue;
598	                try {
599	                    from.put(entry.getKey(), LocalDate.parse(value));
600	                } catch (DateTimeParseException e) {
601	                    throw new InvalidSettingException("A from-date is a date, yyyy-MM-dd, or blank");
602	                }
603	            }
604	        }
605	        body.set(new SettingsInput(limitChanged, limit, floor, terms, latePct, policyChanged, policyDate,
606	                numberingChanged, numberingFrom, gradeTerms, capChanged, cap, from,
607	                thresholdChanged, threshold, perms, graceChanged, graceDays, noteThresholdChanged, noteThreshold,
608	                entryChanged, entryDate, gradeGrace, gradeProofThreshold, potChanged, pot, parentChanged, parent,
609	                fiscalChanged, fiscalStartMonth, alertChanged, alertThreshold, roundingChanged, rounding));
610	    }
611	}
